    for i in range(N):
        while X[i] >= 500 and F > 0:
            X[i] -= 500
            F -= 1
        while X[i] >= 100 and E > 0:
            X[i] -= 100
            E -= 1
        while X[i] >= 50 and D > 0:
            X[i] -= 50
            D -= 1
        while X[i] >= 10 and C > 0:
            X[i] -= 10
            C -= 1
        while X[i] >= 5 and B > 0:
            X[i] -= 5
            B -= 1
